css:
@page{
    size:A4;
    margin:1cm;
}
body{
    font-family:Arial,sans-serif;
    background-color:grey;
}
.header{
    margin-bottom:5px;
    text-aligh:center;
}
.header h1{
    margin-bottom:5px;
    font-weight:bold;
    color:green;

}

.member-section h3,.package-section h3{
   padding-bottom:5px;
}
.detail-row{
    display:flex;
    justify-content:space-between;
